import React, { useEffect, useRef, useState } from 'react';
import p5 from 'p5';

const PendulumSimulator = () => {
  const [pendulumParams, setPendulumParams] = useState({
    length: 200,
    mass: 10,
    gravity: 9.8,
    angle: Math.PI / 4,
    damping: 0.995,
    trailLength: 100,
    timeScale: 0.05, // New parameter to control simulation speed
  });

  const [energy, setEnergy] = useState({
    potential: 0,
    kinetic: 0,
    total: 0,
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showTrail, setShowTrail] = useState(true);
  const [showEnergy, setShowEnergy] = useState(true);
  const [resetFlag, setResetFlag] = useState(0);

  const p5ContainerRef = useRef(null);
  const p5InstanceRef = useRef(null);
  const energyHistoryRef = useRef([]);
  const trailRef = useRef([]);
  const initialEnergyRef = useRef(null);
  const maxEnergyRef = useRef(100); // Store consistent max energy value

  useEffect(() => {
    if (p5InstanceRef.current) {
      p5InstanceRef.current.remove();
      p5InstanceRef.current = null;
    }

    const sketch = (p) => {
      let angle = pendulumParams.angle;
      let angleVelocity = 0;
      let angleAcceleration = 0;

      p.setup = () => {
        p.createCanvas(600, 500);
        resetSimulation();
      };

      p.draw = () => {
        p.background(20);

        const origin = { x: p.width / 2, y: 100 };

        if (!isPaused) {
          // Apply time scaling to make physics more realistic
          const scaledGravity = pendulumParams.gravity * pendulumParams.timeScale;
          
          // Apply physics with time scaling
          angleAcceleration = (-1 * scaledGravity / pendulumParams.length) * p.sin(angle);
          angleVelocity += angleAcceleration;
          angleVelocity *= pendulumParams.damping;
          angle += angleVelocity;

          // Calculate height from the lowest point of the pendulum swing
          const height = pendulumParams.length * (1 - p.cos(angle));
          
          // More stable energy calculations with appropriate scaling
          const kineticEnergy = 0.5 * pendulumParams.mass * Math.pow(angleVelocity * pendulumParams.length, 2);
          const potentialEnergy = pendulumParams.mass * scaledGravity * height;
          const totalEnergy = kineticEnergy + potentialEnergy;

          // Initialize reference energy on first calculation
          if (initialEnergyRef.current === null) {
            initialEnergyRef.current = totalEnergy;
            // Set initial max energy with a buffer
            maxEnergyRef.current = Math.max(totalEnergy * 1.5, 100);
          }

          // Update max energy if current energy exceeds it (with some hysteresis to prevent frequent changes)
          if (totalEnergy > maxEnergyRef.current) {
            maxEnergyRef.current = totalEnergy * 1.2; // Add 20% buffer
          }

          setEnergy({
            kinetic: kineticEnergy,
            potential: potentialEnergy,
            total: totalEnergy,
          });

          const bobPosition = {
            x: origin.x + pendulumParams.length * p.sin(angle),
            y: origin.y + pendulumParams.length * p.cos(angle),
          };

          if (showTrail) {
            trailRef.current.push({ ...bobPosition });
            if (trailRef.current.length > pendulumParams.trailLength) {
              trailRef.current.shift();
            }
          }

          // Ensure positive energy values for display
          energyHistoryRef.current.push({
            kinetic: Math.max(0, kineticEnergy),
            potential: Math.max(0, potentialEnergy),
            total: Math.max(0, totalEnergy),
          });

          if (energyHistoryRef.current.length > 200) {
            energyHistoryRef.current.shift();
          }
        }

        p.fill(200);
        p.stroke(200);
        p.ellipse(origin.x, origin.y, 10, 10);

        const bobPosition = {
          x: origin.x + pendulumParams.length * p.sin(angle),
          y: origin.y + pendulumParams.length * p.cos(angle),
        };

        p.stroke(255);
        p.strokeWeight(2);
        p.line(origin.x, origin.y, bobPosition.x, bobPosition.y);

        p.fill(255, 100, 100);
        p.noStroke();
        p.ellipse(bobPosition.x, bobPosition.y, pendulumParams.mass * 2, pendulumParams.mass * 2);

        if (showTrail && trailRef.current.length > 0) {
          p.noFill();
          p.beginShape();
          trailRef.current.forEach((pos, i) => {
            const alpha = p.map(i, 0, trailRef.current.length - 1, 10, 200);
            p.stroke(255, 100, 100, alpha);
            p.vertex(pos.x, pos.y);
          });
          p.endShape();
        }

        if (showEnergy) {
          drawEnergyGraph(p);
        }
      };

      p.mousePressed = () => {
        const origin = { x: p.width / 2, y: 100 };
        const dx = p.mouseX - origin.x;
        const dy = p.mouseY - origin.y;

        if (p.dist(p.mouseX, p.mouseY, origin.x + pendulumParams.length * p.sin(angle), origin.y + pendulumParams.length * p.cos(angle)) < pendulumParams.mass * 2) {
          const newAngle = p.atan2(dx, dy);
          angle = newAngle;
          angleVelocity = 0;

          // Reset tracking when manually moving pendulum
          trailRef.current = [];
          energyHistoryRef.current = [];
          initialEnergyRef.current = null;
        }
      };

      const drawEnergyGraph = (p) => {
        const graphHeight = 100;
        const graphY = p.height - graphHeight - 20;

        // Draw graph background
        p.fill(30);
        p.rect(20, graphY, p.width - 40, graphHeight);

        if (energyHistoryRef.current.length > 0) {
          // Use consistent maxEnergy value for stable scaling
          const maxEnergy = maxEnergyRef.current;
          
          // Always draw all three energy lines, even if values are 0
          
          // Draw graph grid lines for reference
          p.stroke(60);
          p.strokeWeight(1);
          for (let i = 0; i <= 4; i++) {
            const y = p.map(i/4, 0, 1, graphY + graphHeight, graphY);
            p.line(20, y, p.width - 20, y);
          }
          
          // Kinetic energy line - always blue
          p.stroke(100, 200, 255);
          p.strokeWeight(2);
          p.noFill();
          p.beginShape();
          energyHistoryRef.current.forEach((e, i) => {
            const x = p.map(i, 0, energyHistoryRef.current.length - 1, 20, p.width - 40);
            const y = p.map(Math.min(e.kinetic, maxEnergy), 0, maxEnergy, graphY + graphHeight, graphY);
            // Ensure y is valid and clamped to graph boundaries
            const clampedY = p.constrain(y, graphY, graphY + graphHeight);
            p.vertex(x, clampedY);
          });
          p.endShape();

          // Potential energy line - always yellow
          p.stroke(255, 200, 100);
          p.strokeWeight(2);
          p.noFill();
          p.beginShape();
          energyHistoryRef.current.forEach((e, i) => {
            const x = p.map(i, 0, energyHistoryRef.current.length - 1, 20, p.width - 40);
            const y = p.map(Math.min(e.potential, maxEnergy), 0, maxEnergy, graphY + graphHeight, graphY);
            // Ensure y is valid and clamped to graph boundaries
            const clampedY = p.constrain(y, graphY, graphY + graphHeight);
            p.vertex(x, clampedY);
          });
          p.endShape();

          // Total energy line - always red
          p.stroke(255, 100, 100);
          p.strokeWeight(2);
          p.noFill();
          p.beginShape();
          energyHistoryRef.current.forEach((e, i) => {
            const x = p.map(i, 0, energyHistoryRef.current.length - 1, 20, p.width - 40);
            const y = p.map(Math.min(e.total, maxEnergy), 0, maxEnergy, graphY + graphHeight, graphY);
            // Ensure y is valid and clamped to graph boundaries
            const clampedY = p.constrain(y, graphY, graphY + graphHeight);
            p.vertex(x, clampedY);
          });
          p.endShape();
        }

        // Graph legend - always visible regardless of data
        p.fill(255);
        p.noStroke();
        p.textSize(12);
        p.text("Energy Graph", 25, graphY + 15);

        p.fill(100, 200, 255);
        p.rect(100, graphY + 7, 10, 10);
        p.fill(255);
        p.text("Kinetic", 115, graphY + 15);

        p.fill(255, 200, 100);
        p.rect(170, graphY + 7, 10, 10);
        p.fill(255);
        p.text("Potential", 185, graphY + 15);

        p.fill(255, 100, 100);
        p.rect(250, graphY + 7, 10, 10);
        p.fill(255);
        p.text("Total", 265, graphY + 15);
      };

      const resetSimulation = () => {
        angle = pendulumParams.angle;
        angleVelocity = 0;
        angleAcceleration = 0;
        trailRef.current = [];
        energyHistoryRef.current = [];
        initialEnergyRef.current = null;
        maxEnergyRef.current = 100; // Reset max energy on simulation reset
      };
    };

    if (p5ContainerRef.current) {
      p5InstanceRef.current = new p5(sketch, p5ContainerRef.current);
    }

    return () => {
      if (p5InstanceRef.current) {
        p5InstanceRef.current.remove();
        p5InstanceRef.current = null;
      }
    };
  }, [pendulumParams, isPaused, showTrail, showEnergy, resetFlag]);

  const handleReset = () => {
    trailRef.current = [];
    energyHistoryRef.current = [];
    initialEnergyRef.current = null;
    maxEnergyRef.current = 100; // Reset max energy on manual reset
    setResetFlag((prev) => prev + 1);
  };

  // Calculate display values for UI
  const getDisplayDamping = () => {
    // Convert internal damping (0.980-1.000) to display scale (0-1)
    return ((1 - pendulumParams.damping) / 0.02).toFixed(2);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    
    if (name === "damping") {
      // Convert from display scale (0-1) to internal scale (0.98-1)
      const internalValue = 1 - (parseFloat(value) * 0.02);
      setPendulumParams(prev => ({
        ...prev,
        [name]: internalValue,
      }));
    } else {
      setPendulumParams(prev => ({
        ...prev,
        [name]: parseFloat(value),
      }));
    }
    
    // Reset energy history when parameters change
    energyHistoryRef.current = [];
    initialEnergyRef.current = null;
    maxEnergyRef.current = 100; // Reset max energy when parameters change
  };

  const formatEnergy = (value) => {
    if (!isFinite(value) || value < 0) return "0.00";
    return Math.round(value * 100) / 100;
  };

  return (
    <div className="w-screen mx-auto p-4 bg-gray-800 text-white">
      <h1 className="text-2xl font-bold mb-4">Advanced Pendulum Simulator</h1>

      <div className="flex flex-col lg:flex-row gap-4">
        <div className="lg:w-2/3 flex justify-center">
          <div ref={p5ContainerRef} className="bg-black rounded-lg overflow-hidden"></div>
        </div>

        <div className="lg:w-1/3 bg-gray-700 p-4 rounded-lg">
          <h2 className="text-lg font-semibold mb-4">Controls</h2>

          <div className="grid gap-4">
            <div>
              <label className="block text-sm mb-1">Length: {pendulumParams.length}</label>
              <input
                type="range"
                name="length"
                min="50"
                max="300"
                value={pendulumParams.length}
                onChange={handleInputChange}
                className="w-full accent-blue-500"
              />
            </div>

            <div>
              <label className="block text-sm mb-1">Mass: {pendulumParams.mass}</label>
              <input
                type="range"
                name="mass"
                min="1"
                max="20"
                value={pendulumParams.mass}
                onChange={handleInputChange}
                className="w-full accent-blue-500"
              />
            </div>

            <div>
              <label className="block text-sm mb-1">Gravity: {pendulumParams.gravity.toFixed(1)} m/s²</label>
              <input
                type="range"
                name="gravity"
                min="0.1"
                max="15"
                step="0.1"
                value={pendulumParams.gravity}
                onChange={handleInputChange}
                className="w-full accent-blue-500"
              />
            </div>

            <div>
              <label className="block text-sm mb-1">
                Initial Angle: {Math.round((pendulumParams.angle * 180) / Math.PI)}°
              </label>
              <input
                type="range"
                name="angle"
                min={-Math.PI / 2}
                max={Math.PI / 2}
                step={0.01}
                value={pendulumParams.angle}
                onChange={handleInputChange}
                className="w-full accent-blue-500"
              />
            </div>

            <div>
              <label className="block text-sm mb-1">Damping: {getDisplayDamping()}</label>
              <input
                type="range"
                name="damping"
                min="0"
                max="1"
                step="0.01"
                value={getDisplayDamping()}
                onChange={handleInputChange}
                className="w-full accent-blue-500"
              />
            </div>

            <div>
              <label className="block text-sm mb-1">Trail Length: {pendulumParams.trailLength}</label>
              <input
                type="range"
                name="trailLength"
                min="0"
                max="200"
                step="1"
                value={pendulumParams.trailLength}
                onChange={handleInputChange}
                className="w-full accent-blue-500"
              />
            </div>

            <div className="flex flex-col gap-2">
              {/* <button
                onClick={() => setIsPaused(!isPaused)}
                className="bg-blue-600 hover:bg-blue-700 py-2 px-4 rounded-md"
              >
                {isPaused ? "Resume" : "Pause"}
              </button> */}

              <button
                onClick={handleReset}
                className="bg-red-600 hover:bg-red-700 py-2 px-4 rounded-md"
              >
                Reset
              </button>
            </div>

            <div className="flex gap-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={showTrail}
                  onChange={() => setShowTrail(!showTrail)}
                  className="mr-2"
                />
                Show Trail
              </label>

              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={showEnergy}
                  onChange={() => setShowEnergy(!showEnergy)}
                  className="mr-2"
                />
                Show Energy Graph
              </label>
            </div>
          </div>

          <div className="mt-4 text-sm text-gray-300">
            <p>Click and drag the pendulum bob to reposition it.</p>
            <p>Adjust parameters to see how they affect the motion and energy.</p>
          </div>
        </div>
      </div>
      
      <div className="mt-4 p-4 bg-gray-700 rounded-lg">
        <h2 className="text-lg font-semibold mb-2">Energy Values</h2>
        <div className="grid grid-cols-3 gap-2">
          <div className="p-2 bg-gray-800 rounded-md">
            <div className="text-sm text-blue-300">Kinetic Energy</div>
            <div className="text-lg">{formatEnergy(energy.kinetic)}</div>
          </div>
          <div className="p-2 bg-gray-800 rounded-md">
            <div className="text-sm text-yellow-300">Potential Energy</div>
            <div className="text-lg">{formatEnergy(energy.potential)}</div>
          </div>
          <div className="p-2 bg-gray-800 rounded-md">
            <div className="text-sm text-red-300">Total Energy</div>
            <div className="text-lg">{formatEnergy(energy.total)}</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PendulumSimulator;